func generateDefaultTemplates(r RootFamilyDefinition) []sfTemplate {
	var list []sfTemplate
	for i := 1; i <= 11; i++ {
		list = append(list, sfTemplate{
			name:       fmt.Sprintf("%s — Specialized Division %d", r.CanonicalName, i),
			def:        fmt.Sprintf("Standard commercial classification for specialized %s equipment, assets and market units (Division %d).", strings.ToLower(r.CanonicalName), i),
			inclusions: []string{fmt.Sprintf("Commercial %s line %d", strings.ToLower(r.CanonicalName), i)},
			exclusions: []string{"Unrelated non-commercial items"},
			examples:   []string{fmt.Sprintf("Primary %s unit type %d", strings.ToLower(r.CanonicalName), i)},
			attrs:      []string{"spec_rating", "commercial_grade", "country_of_origin"},
		})
	}
	return list
}
